(* [comment removed for export] *)
Lemma slots_sep_any : forall L st X c1 k1 c2 k2,
  alayout_ok L -> awf L st X -> 1 <= c1 < K_NUM_CLASSES -> 1 <= c2 < K_NUM_CLASSES ->
  0 <= k1 < ndist st c1 -> 0 <= k2 < ndist st c2 -> (c1 <> c2 \/ k1 <> k2) ->
